const items = $input.all();
const results = [];

for (const item of items) {
  const buffer = await this.helpers.getBinaryDataBuffer(item, 'data');

  // DOCX is a ZIP file - find word/document.xml inside
  const bufStr = buffer.toString('binary');
  const marker = 'word/document.xml';
  const idx = bufStr.indexOf(marker);

  if (idx === -1) {
    // Not a valid DOCX, try as plain text
    results.push({ json: { extracted_text: buffer.toString('utf-8'), source_type: 'docx_fallback' } });
    continue;
  }

  const { execSync } = require('child_process');
  const fs = require('fs');
  const os = require('os');
  const path = require('path');

  // Write buffer to temp file
  const tmpFile = path.join(os.tmpdir(), `docx_${Date.now()}.docx`);
  fs.writeFileSync(tmpFile, buffer);

  try {
    const xml = execSync(`unzip -p "${tmpFile}" word/document.xml 2>/dev/null`, { encoding: 'utf-8', maxBuffer: 50 * 1024 * 1024 });

    const text = xml
      .replace(/<w:br[^>]*\/>/gi, '\n')
      .replace(/<w:p[^>]*>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/\n{3,}/g, '\n\n')
      .trim();

    results.push({ json: { extracted_text: text, source_type: 'docx' } });
  } catch (e) {
    results.push({ json: { extracted_text: buffer.toString('utf-8'), source_type: 'docx_error', error: e.message } });
  } finally {
    try { fs.unlinkSync(tmpFile); } catch(e) {}
  }
}

return results;

// Convert spreadsheet rows to text string
const items = $input.all();
let text = '';

if (items.length > 0) {
  // Get headers from first item keys
  const headers = Object.keys(items[0].json).filter(k => !k.startsWith('_'));
  text += headers.join(' | ') + '\n';
  text += headers.map(() => '---').join(' | ') + '\n';

  for (const item of items) {
    const row = headers.map(h => String(item.json[h] || '')).join(' | ');
    text += row + '\n';
  }
}

return [{
  json: {
    text: text,
    source_type: 'spreadsheet',
    char_count: text.length,
    row_count: items.length
  }
}];

// Decode binary buffer to UTF-8 text
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const text = buffer.toString('utf-8');

return [{
  json: {
    text: text,
    source_type: 'plaintext',
    char_count: text.length
  }
}];

const item = $input.item;
const contractText = (item.json.text || '').substring(0, 15000);

// Gather metadata from webhook body/headers
const orgId = item.json.org_id || $('Webhook - Ingest Contract').item.json.body?.org_id || '';
const tenantId = item.json.tenant_id || $('Webhook - Ingest Contract').item.json.body?.tenant_id || '';
const sourceName = item.json.source_name || $('Webhook - Ingest Contract').item.json.body?.source_name || 'unknown';
const modelProvider = item.json.model_provider || $('Webhook - Ingest Contract').item.json.body?.model_provider || $('Webhook - Ingest Contract').item.json.headers?.['x-model-provider'] || 'openai';

const systemPrompt = `You are a contract analysis specialist. Your ONLY job is to extract factual information from the contract text provided. You must NEVER invent, assume, or hallucinate any information.

RULES:
1. If information is NOT explicitly stated in the contract, return "NOT SPECIFIED" for that field.
2. Extract exact wording where possible. Use direct quotes for conditions and terms.
3. If a clause is ambiguous, flag it as "REQUIRES REVIEW" and quote the exact ambiguous text.
4. Never fill in "typical" or "industry standard" values. Only extract what is written.

Extract the following into a JSON object:

{
  "contract_metadata": {
    "contract_title": "",
    "effective_date": "",
    "expiry_date": "",
    "auto_renewal": "",
    "notice_period_days": "",
    "governing_law": "",
    "service_provider": "",
    "service_consumer": "",
    "contract_reference": "",
    "organisation": "",
    "industry": "",
    "review_date": "Next scheduled review date (ISO or human-readable). Set to NOT SPECIFIED if not found."
  },
  "sla_table": [
    {
      "priority": "P1 / Critical",
      "description": "",
      "response_time": "",
      "resolution_time": "",
      "mitigation_time": "",
      "availability_target": "",
      "measurement_period": "",
      "conditions_triggering_this_priority": "",
      "exact_contract_clause_reference": "",
      "penalties_or_credits": ""
    }
  ],
  "uptime_commitments": {
    "target_percentage": "",
    "measurement_window": "",
    "exclusions": "",
    "calculation_method": "",
    "exact_clause_reference": ""
  },
  "service_credits": [
    {
      "trigger_condition": "",
      "credit_percentage": "",
      "cap_on_credits": "",
      "claim_process": "",
      "claim_deadline": "",
      "exact_clause_reference": ""
    }
  ],
  "concerns_for_service_provider": [
    {
      "concern": "",
      "relevant_clause": "",
      "risk_level": "HIGH / MEDIUM / LOW",
      "recommendation": ""
    }
  ],
  "breach_clauses": [
    {
      "breach_type": "",
      "consequence": "",
      "cure_period": "",
      "exact_clause_reference": ""
    }
  ],
  "key_contacts": {
    "provider_contact": "",
    "consumer_contact": "",
    "escalation_path": ""
  },
  "extraction_confidence": {
    "overall_confidence": "HIGH / MEDIUM / LOW",
    "fields_marked_not_specified": [],
    "fields_requiring_review": [],
    "notes": ""
  }
}

IMPORTANT: The "extraction_confidence" section is mandatory. List every field you could NOT find. This is how we ensure zero hallucination.`;

return [{
  json: {
    systemPrompt,
    contractText,
    org_id: orgId,
    tenant_id: tenantId,
    source_name: sourceName,
    source_type: item.json.source_type || 'unknown',
    model_provider: modelProvider,
    char_count: contractText.length,
    _repair_attempt: item.json._repair_attempt || 0
  }
}];

// Extract text from Claude API response
const item = $input.item;
const response = item.json;

let extractionText = '';
if (response.content && Array.isArray(response.content) && response.content.length > 0) {
  extractionText = response.content[0].text || '';
} else if (response.text) {
  extractionText = response.text;
}

return [{
  json: {
    extraction_response: extractionText,
    model_used: 'claude-sonnet-4-20250514',
    _model_used: 'claude',
    org_id: $('Prepare AI Prompt').item.json.org_id,
    tenant_id: $('Prepare AI Prompt').item.json.tenant_id,
    source_name: $('Prepare AI Prompt').item.json.source_name,
    source_type: $('Prepare AI Prompt').item.json.source_type,
    _repair_attempt: $('Prepare AI Prompt').item.json._repair_attempt
  }
}];

// Normalize OpenAI response
const item = $input.item;
let extractionText = '';

if (item.json.message?.content) {
  extractionText = item.json.message.content;
} else if (item.json.text) {
  extractionText = item.json.text;
} else if (typeof item.json === 'string') {
  extractionText = item.json;
}

return [{
  json: {
    extraction_response: extractionText,
    model_used: 'gpt-4o',
    _model_used: 'openai',
    org_id: $('Prepare AI Prompt').item.json.org_id,
    tenant_id: $('Prepare AI Prompt').item.json.tenant_id,
    source_name: $('Prepare AI Prompt').item.json.source_name,
    source_type: $('Prepare AI Prompt').item.json.source_type,
    _repair_attempt: $('Prepare AI Prompt').item.json._repair_attempt
  }
}];

const item = $input.item;
const raw = item.json.extraction_response || '';

// Strip markdown code fences
let cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = null;
let parseError = null;
let needsRepair = false;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
  needsRepair = true;
}

// Validate ALL 8 required sections
if (parsed) {
  const requiredSections = [
    'contract_metadata',
    'sla_table',
    'uptime_commitments',
    'service_credits',
    'concerns_for_service_provider',
    'breach_clauses',
    'key_contacts',
    'extraction_confidence'
  ];
  const missingSections = requiredSections.filter(s => !parsed[s]);
  if (missingSections.length > 0) {
    parseError = `Missing required sections: ${missingSections.join(', ')}`;
    needsRepair = true;
  }
}

// Count NOT SPECIFIED and REQUIRES REVIEW fields
let notSpecifiedCount = 0;
let requiresReviewCount = 0;

if (parsed) {
  const jsonStr = JSON.stringify(parsed);
  notSpecifiedCount = (jsonStr.match(/NOT SPECIFIED/g) || []).length;
  requiresReviewCount = (jsonStr.match(/REQUIRES REVIEW/g) || []).length;
}

// FIX 13: Compute extraction confidence from actual field population
if (parsed && !needsRepair) {
  // Count all string fields in the extraction
  let totalFields = 0;
  let populatedFields = 0;

  function countFields(obj) {
    if (typeof obj === 'string') {
      totalFields++;
      if (obj && obj !== 'NOT SPECIFIED' && obj !== 'REQUIRES REVIEW' && obj.trim() !== '') {
        populatedFields++;
      }
    } else if (Array.isArray(obj)) {
      obj.forEach(item => countFields(item));
    } else if (obj && typeof obj === 'object') {
      Object.values(obj).forEach(val => countFields(val));
    }
  }

  // Count fields excluding extraction_confidence itself
  const { extraction_confidence, ...dataFields } = parsed;
  countFields(dataFields);

  const populationRate = totalFields > 0 ? populatedFields / totalFields : 0;
  let computedConfidence = 'LOW';
  if (populationRate > 0.8 && requiresReviewCount <= 3) {
    computedConfidence = 'HIGH';
  } else if (populationRate >= 0.5 && requiresReviewCount <= 3) {
    computedConfidence = 'MEDIUM';
  }

  // Override AI's confidence with computed value
  if (parsed.extraction_confidence) {
    parsed.extraction_confidence.overall_confidence = computedConfidence;
  }
}

return [{
  json: {
    extraction: parsed,
    extraction_raw: raw,
    _needs_repair: needsRepair,
    _parse_error: parseError,
    _repair_attempt: item.json._repair_attempt || 0,
    _not_specified_count: notSpecifiedCount,
    _requires_review_count: requiresReviewCount,
    model_used: item.json.model_used,
    _model_used: item.json._model_used || item.json.model_used,
    org_id: item.json.org_id,
    tenant_id: item.json.tenant_id,
    source_name: item.json.source_name,
    source_type: item.json.source_type
  }
}];

const item = $input.item;
const originalResponse = item.json.extraction_raw || '';
const parseError = item.json._parse_error || 'Unknown parse error';
const modelUsed = item.json._model_used || 'openai';

const repairPrompt = `Previous extraction returned invalid JSON. Error: ${parseError}.

Original response (first 5000 chars):
${originalResponse.substring(0, 5000)}

Fix the JSON and return a valid JSON object with all required sections: contract_metadata, sla_table, uptime_commitments, service_credits, concerns_for_service_provider, breach_clauses, key_contacts, extraction_confidence.
Return ONLY the corrected JSON, no markdown fences or extra text.`;

return [{
  json: {
    systemPrompt: $('Prepare AI Prompt').item.json.systemPrompt,
    contractText: repairPrompt,
    org_id: item.json.org_id,
    tenant_id: item.json.tenant_id,
    source_name: item.json.source_name,
    source_type: item.json.source_type,
    model_provider: modelUsed,
    _repair_attempt: 1
  }
}];

const item = $input.item;
const results = item.json;
const extraction = $('Parse + Validate JSON').item.json.extraction;

// Check if org was found
let orgRecordId = null;
if (results && results.id) {
  orgRecordId = results.id;
}

return [{
  json: {
    org_found: !!orgRecordId,
    org_record_id: orgRecordId,
    org_name: extraction.contract_metadata.organisation || 'Unknown Organisation',
    extraction: extraction,
    org_id: $('Parse + Validate JSON').item.json.org_id,
    tenant_id: $('Parse + Validate JSON').item.json.tenant_id,
    source_name: $('Parse + Validate JSON').item.json.source_name,
    source_type: $('Parse + Validate JSON').item.json.source_type,
    model_used: $('Parse + Validate JSON').item.json.model_used,
    _not_specified_count: $('Parse + Validate JSON').item.json._not_specified_count,
    _requires_review_count: $('Parse + Validate JSON').item.json._requires_review_count
  }
}];

// Merge org record ID from either found or created path
const item = $input.item;
let orgRecordId = '';

// From the found path
if (item.json.org_record_id) {
  orgRecordId = item.json.org_record_id;
}
// From the created path (Airtable returns id on create)
if (item.json.id) {
  orgRecordId = item.json.id;
}

// Pull extraction data forward
const checkResult = $('Check Org Result').item.json;

return [{
  json: {
    org_record_id: orgRecordId,
    extraction: checkResult.extraction,
    org_id: checkResult.org_id,
    tenant_id: checkResult.tenant_id,
    source_name: checkResult.source_name,
    source_type: checkResult.source_type,
    model_used: checkResult.model_used,
    _not_specified_count: checkResult._not_specified_count,
    _requires_review_count: checkResult._requires_review_count
  }
}];

// Prepare SLA table items for batch creation
const item = $input.item;
const contractRecordId = item.json.id;
const orgRecordId = $('Merge Org Paths').item.json.org_record_id;
const extraction = $('Merge Org Paths').item.json.extraction;
const slaTable = extraction.sla_table || [];

const items = slaTable.map((sla, index) => ({
  json: {
    contract_record_id: contractRecordId,
    priority: sla.priority || '',
    description: sla.description || '',
    response_time: sla.response_time || '',
    resolution_time: sla.resolution_time || '',
    mitigation_time: sla.mitigation_time || '',
    availability_target: sla.availability_target || '',
    measurement_period: sla.measurement_period || '',
    conditions: sla.conditions_triggering_this_priority || '',
    clause_reference: sla.exact_contract_clause_reference || '',
    penalties_or_credits: sla.penalties_or_credits || '',
    source: 'Extracted',
    org_record_id: orgRecordId,
    _index: index,
    _total: slaTable.length
  }
}));

return items.length > 0 ? items : [{ json: { _skip: true, contract_record_id: contractRecordId } }];

// Prepare uptime commitment record
const contractRecordId = $('Airtable - Create Contract').item.json.id;
const orgRecordId = $('Merge Org Paths').item.json.org_record_id;
const extraction = $('Merge Org Paths').item.json.extraction;
const uptime = extraction.uptime_commitments || {};

return [{
  json: {
    contract_record_id: contractRecordId,
    target_percentage: uptime.target_percentage || '',
    measurement_window: uptime.measurement_window || '',
    exclusions: uptime.exclusions || '',
    calculation_method: uptime.calculation_method || '',
    clause_reference: uptime.exact_clause_reference || '',
    org_record_id: orgRecordId
  }
}];

// Prepare service credit items for batch creation
const contractRecordId = $('Airtable - Create Contract').item.json.id;
const orgRecordId = $('Merge Org Paths').item.json.org_record_id;
const extraction = $('Merge Org Paths').item.json.extraction;
const credits = extraction.service_credits || [];

const items = credits.map((credit, index) => ({
  json: {
    contract_record_id: contractRecordId,
    trigger_condition: credit.trigger_condition || '',
    credit_percentage: credit.credit_percentage || '',
    cap_on_credits: credit.cap_on_credits || '',
    claim_process: credit.claim_process || '',
    claim_deadline: credit.claim_deadline || '',
    clause_reference: credit.exact_clause_reference || '',
    org_record_id: orgRecordId,
    _index: index,
    _total: credits.length
  }
}));

return items.length > 0 ? items : [{ json: { _skip: true, contract_record_id: contractRecordId } }];

// Prepare concern items for batch creation
const contractRecordId = $('Airtable - Create Contract').item.json.id;
const orgRecordId = $('Merge Org Paths').item.json.org_record_id;
const extraction = $('Merge Org Paths').item.json.extraction;
const concerns = extraction.concerns_for_service_provider || [];

const items = concerns.map((concern, index) => ({
  json: {
    contract_record_id: contractRecordId,
    concern: concern.concern || '',
    relevant_clause: concern.relevant_clause || '',
    risk_level: concern.risk_level || '',
    recommendation: concern.recommendation || '',
    org_record_id: orgRecordId,
    _index: index,
    _total: concerns.length
  }
}));

return items.length > 0 ? items : [{ json: { _skip: true, contract_record_id: contractRecordId } }];

// Prepare breach clause items for batch creation
const contractRecordId = $('Airtable - Create Contract').item.json.id;
const orgRecordId = $('Merge Org Paths').item.json.org_record_id;
const extraction = $('Merge Org Paths').item.json.extraction;
const breaches = extraction.breach_clauses || [];

const items = breaches.map((breach, index) => ({
  json: {
    contract_record_id: contractRecordId,
    breach_type: breach.breach_type || '',
    consequence: breach.consequence || '',
    cure_period: breach.cure_period || '',
    clause_reference: breach.exact_clause_reference || '',
    org_record_id: orgRecordId,
    _index: index,
    _total: breaches.length
  }
}));

return items.length > 0 ? items : [{ json: { _skip: true, contract_record_id: contractRecordId } }];

// Final summary — log success
const contractRecord = $('Airtable - Create Contract').item.json;
const extraction = $('Merge Org Paths').item.json.extraction;
const checkResult = $('Merge Org Paths').item.json;

const slaCount = (extraction.sla_table || []).length;
const creditsCount = (extraction.service_credits || []).length;
const concernsCount = (extraction.concerns_for_service_provider || []).length;
const breachCount = (extraction.breach_clauses || []).length;

const summary = {
  status: 'complete',
  contract_id: contractRecord.id || 'unknown',
  contract_title: extraction.contract_metadata.contract_title || 'Untitled',
  org_id: checkResult.org_id,
  tenant_id: checkResult.tenant_id,
  org_record_id: checkResult.org_record_id,
  model_used: checkResult.model_used,
  source_name: checkResult.source_name,
  source_type: checkResult.source_type,
  records_created: {
    sla_priorities: slaCount,
    uptime_commitments: 1,
    service_credits: creditsCount,
    concerns: concernsCount,
    breach_clauses: breachCount,
    total: slaCount + 1 + creditsCount + concernsCount + breachCount + 2
  },
  extraction_confidence: extraction.extraction_confidence.overall_confidence,
  not_specified_count: checkResult._not_specified_count,
  requires_review_count: checkResult._requires_review_count,
  completed_at: new Date().toISOString()
};

console.log('SLA Contract Manager — Pipeline Complete', JSON.stringify(summary, null, 2));

return [{ json: summary }];

const item = $input.item;
const errorData = {
  nodeName: item.json.execution?.error?.node?.name || item.json.node?.name || 'unknown',
  errorMessage: item.json.execution?.error?.message || item.json.error?.message || 'Unknown error',
  inputData: JSON.stringify(item.json).substring(0, 500),
  timestamp: new Date().toISOString()
};

console.log('WORKFLOW ERROR:', JSON.stringify(errorData, null, 2));

return [{ json: errorData }];

// Try to find contract_record_id from the execution context
const execution = $json;
let contractId = null;

// Check if contract was created before the error
try {
  const data = execution.execution?.data;
  if (data?.resultData?.runData?.['Airtable - Create Contract']) {
    const contractResult = data.resultData.runData['Airtable - Create Contract'];
    contractId = contractResult[0]?.data?.main?.[0]?.[0]?.json?.id;
  }
} catch(e) {}

return [{ json: { ...execution, contract_record_id: contractId, has_contract: !!contractId } }];

return [{
  json: {
    status: 'failed',
    error: 'JSON validation failed after repair retry',
    timestamp: new Date().toISOString()
  }
}];
